import { select } from "d3-selection";
import { geoPath, geoEquirectangular } from "d3-geo";
import { jurisdictionColorScale } from "./scales";

export const drawMap = (map, fines) => {

  map.features.forEach(jurisdiction => {
    const props = jurisdiction.properties;
    props.fines = fines.filter(fines => 
      fines.JURISDICTION === props.name);
  });

  const width = 1000;
  const height = 400;
  const innerWidth = width - 200;
  const innerHeight = height - 100;

  const svg = select("#map")
    .append("svg")                              
    .attr("viewBox", `0 0 ${width} ${height}`);  

  const projection = geoEquirectangular();

  projection.fitExtent([[20, 20], [width - 10, height - 10]], map);
  
  const geoPathGenerator = geoPath()
    .projection(projection);          

  svg
    .selectAll(".jurisdiction-path")
    .data(map.features)             
    .join("path")                    
      .attr("class", "jurisdiction-path") 
      .attr("d", geoPathGenerator)
      .attr("fill", d => d.properties.fines[0].FINES > 0 
        ? jurisdictionColorScale(d.properties.fines[0].FINES) 
        : "#f8fcff")
      .attr("stroke", "#09131b")
      .attr("stroke-opacity", 0.4);    

  // Replace these with your actual width/height and fines domain
  const minFines = d3.min(map.features, d => d.properties.fines[0].FINES);
  const maxFines = d3.max(map.features, d => d.properties.fines[0].FINES);

  // Legend dimensions
  const legendWidth = 300;
  const legendHeight = 10;

  // Add defs for gradient
  const defs = svg.append("defs");

  const linearGradient = defs.append("linearGradient")
    .attr("id", "legend-gradient");

  linearGradient.selectAll("stop")
    .data(d3.range(0, 1.01, 0.01)) // smooth gradient
    .enter()
    .append("stop")
    .attr("offset", d => `${d * 100}%`)
    .attr("stop-color", d => jurisdictionColorScale(
      minFines + d * (maxFines - minFines)
    ));

  // Add legend group to SVG
  const legendGroup = svg.append("g")
    .attr("class", "legend")
    .attr("transform", `translate(${30}, ${height - 40})`);

  // Draw the gradient bar
  legendGroup.append("rect")
    .attr("width", legendWidth)
    .attr("height", legendHeight)
    .style("fill", "url(#legend-gradient)")
    .attr("stroke", "#000")
    .attr("stroke-width", 0.4);

  // Create scale for legend axis
  const legendScale = d3.scaleLinear()
    .domain([minFines, maxFines])
    .range([0, legendWidth]);

  const legendAxis = d3.axisBottom(legendScale)
  .tickValues([legendScale.domain()[0], legendScale.domain()[1]])
  .tickFormat(d3.format("$,.0f"));

  // Append the axis below the gradient bar
  legendGroup.append("g")
    .attr("transform", `translate(0, ${legendHeight})`)
    .call(legendAxis)
    .selectAll("text")
    .style("font-size", "10px");

  // Add title text
  legendGroup.append("text")
    .attr("x", legendWidth / 2)
    .attr("y", -6)
    .attr("text-anchor", "middle")
    .style("fill", "#fff")
    .style("font-size", "12px")
    .text("Speeding Fines");

};













